set-variable.value:
@{
		var tp = context.Request.Headers.GetValueOrDefault("traceparent", "");
		if (System.Text.RegularExpressions.Regex.IsMatch(tp, "^00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}$")) { return tp; }
		return "00-" + Guid.NewGuid().ToString("N") + "-" + Guid.NewGuid().ToString("N").Substring(0, 16) + "-01";
	}
